def combination_sum(candidates, target):
    c = sorted(candidates)
    out = []
    def go(start, rest, cur):
        if rest == 0:
            out.append(cur[:])
            return
        for i in range(start, len(c)):
            if c[i] > rest:
                break
            cur.append(c[i])
            go(i, rest - c[i], cur)
            cur.pop()
    go(0, target, [])
    return sorted(out)
